(()=>{
'use strict';
if(window.__gtavModsShareV1)return;window.__gtavModsShareV1=true;
const SHARE_ICON='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v12"/><path d="m8 7 4-4 4 4"/><path d="M5 11v7a3 3 0 0 0 3 3h8a3 3 0 0 0 3-3v-7"/></svg>';
const waitForCards=()=>new Promise(resolve=>{const found=document.querySelector('.library-card');if(found){resolve();return}const observer=new MutationObserver(()=>{if(document.querySelector('.library-card')){observer.disconnect();resolve()}});observer.observe(document.documentElement,{childList:true,subtree:true});setTimeout(()=>{observer.disconnect();resolve()},6000)});
function shareUrl(id){const url=new URL('/downloads.html',location.origin);url.searchParams.set('mod',id);url.hash='mods';return url.href}
async function share(card,button){const id=card.dataset.id||'';if(!id)return;const title=card.querySelector('h3')?.textContent?.trim()||'GTA V iOS Mod';const subtitle=card.querySelector('.library-card-subtitle')?.textContent?.trim();const text=subtitle?`${title} — ${subtitle}`:title;const url=shareUrl(id);try{if(navigator.share){await navigator.share({title,text,url});return}await navigator.clipboard.writeText(url);button.classList.add('is-copied');button.setAttribute('aria-label','Link copied');setTimeout(()=>{button.classList.remove('is-copied');button.setAttribute('aria-label',`Share ${title}`)},1400)}catch(error){if(error?.name==='AbortError')return;try{await navigator.clipboard.writeText(url);button.classList.add('is-copied');setTimeout(()=>button.classList.remove('is-copied'),1400)}catch{}}
}
function enhanceCard(card){if(card.querySelector('.mod-share-button'))return;const meta=card.querySelector('.library-card-meta');if(!meta)return;const children=[...meta.children];const countNode=children[1]||null;const right=document.createElement('span');right.className='library-card-meta-actions';if(countNode)right.append(countNode);const button=document.createElement('button');button.type='button';button.className='mod-share-button';button.innerHTML=SHARE_ICON;const title=card.querySelector('h3')?.textContent?.trim()||'mod';button.setAttribute('aria-label',`Share ${title}`);button.title='Share';button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();share(card,button)});right.append(button);meta.append(right)}
function focusSharedCard(){const id=new URL(location.href).searchParams.get('mod');if(!id)return;const card=[...document.querySelectorAll('.library-card')].find(node=>node.dataset.id===id);if(!card)return;card.hidden=false;card.classList.add('is-shared-target');const panel=card.querySelector('.collection-panel'),toggle=card.querySelector('.collection-toggle');if(panel&&toggle){panel.hidden=false;card.classList.add('is-open');toggle.setAttribute('aria-expanded','true')}setTimeout(()=>card.scrollIntoView({behavior:'smooth',block:'center'}),160);setTimeout(()=>card.classList.remove('is-shared-target'),2800)}
async function init(){if(document.body?.dataset.page!=='downloads')return;await waitForCards();document.querySelectorAll('.library-card').forEach(enhanceCard);focusSharedCard();const feed=document.querySelector('.library-feed');if(feed)new MutationObserver(()=>feed.querySelectorAll('.library-card').forEach(enhanceCard)).observe(feed,{childList:true,subtree:true})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
